#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    int c;

    int a(
        const int & m,
        const int & f)
    {
        return m + f;    
    }
    heartlib()
    {

        // c = a(1, 2)
        c = a(1, 2);
    }
};

