function output = heartlib()
% output = heartlib()
%
%    a_m(f) = m+f where f,m ∈ ℤ 
%                        c = a(1, 2)
%                        
    % c = a(1, 2)

    c = a(1, 2);
    function [ret] = a(m, f)
        assert(numel(m) == 1);
        assert(numel(f) == 1);

        ret = m + f;
    end

    output.c = c;
    output.a = @a;
end

